-- Move the app's business logic into the database.
--   * forecast / best-time / insights as SQL functions (server decides "now" and the timezone)
--   * session lifecycle as RPC functions; clients can no longer write to `sessions` directly
--   * reminders + notifications generated by a pg_cron job (works with the app closed)
--   * wash/dry programs as a table, default residence assigned at signup
--   * realtime on sessions + notifications

------------------------------------------------------------------------------
-- 1. Schema additions
------------------------------------------------------------------------------
alter table public.residences add column timezone text not null default 'Europe/Paris';

-- time_scale: 1 = real time, 60 = demo (a minute per second). Used for timer length and
-- for the "still not collected" follow-up delay.
alter table public.sessions add column time_scale int not null default 1 check (time_scale in (1, 60));
create index sessions_active_idx on public.sessions (ends_at) where status = 'active';

create table public.programs (
  id         uuid primary key default gen_random_uuid(),
  kind       public.session_kind not null check (kind in ('wash', 'dry')),
  name       text not null,
  minutes    int  not null check (minutes > 0),
  sort_order int  not null default 0,
  unique (kind, name)
);
insert into public.programs (kind, name, minutes, sort_order) values
  ('wash', 'Cottons 40°',   45, 0), ('wash', 'Delicates 30°', 30, 1), ('wash', 'Quick 20°', 20, 2),
  ('dry',  'Normal',        40, 0), ('dry',  'Gentle',        30, 1), ('dry',  'Quick',     20, 2);

alter table public.programs enable row level security;
create policy "programs select" on public.programs for select to anon, authenticated using (true);
create policy "programs insert" on public.programs for insert to authenticated with check (public.is_admin());
create policy "programs update" on public.programs for update to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "programs delete" on public.programs for delete to authenticated using (public.is_admin());

------------------------------------------------------------------------------
-- 2. Helpers
------------------------------------------------------------------------------
create or replace function public.level_of(c numeric)
returns smallint language sql immutable set search_path = '' as $$
  select (case when c < 0.32 then 0 when c < 0.52 then 1 when c < 0.8 then 2 else 3 end)::smallint
$$;

create or replace function public.level_name(l smallint)
returns text language sql immutable set search_path = '' as $$
  select (array['Quiet', 'Moderate', 'Busy', 'Very busy'])[l + 1]
$$;

-- The caller's residence (their profile's, else the first one) - also works signed out.
create or replace function public.current_residence()
returns public.residences language plpgsql stable set search_path = '' as $$
declare r public.residences;
begin
  select x.* into r from public.residences x
    join public.profiles p on p.residence_id = x.id
    where p.id = (select auth.uid());
  if not found then
    select x.* into r from public.residences x order by x.sort_order limit 1;
  end if;
  return r;
end $$;

create or replace function public.user_tz()
returns text language sql stable set search_path = '' as $$
  select coalesce((public.current_residence()).timezone, 'Europe/Paris')
$$;

create or replace function public.server_time()
returns timestamptz language sql stable set search_path = '' as $$ select now() $$;

-- New users get the default residence automatically.
create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  insert into public.profiles (id, display_name, residence_id)
  values (
    new.id,
    coalesce(new.raw_user_meta_data ->> 'display_name', split_part(new.email, '@', 1)),
    (select r.id from public.residences r order by r.sort_order limit 1)
  );
  return new;
end $$;

------------------------------------------------------------------------------
-- 3. Forecast
------------------------------------------------------------------------------
-- Hourly forecast for one day (default: today in the residence's timezone).
-- is_recommended = one of the 3 quietest remaining hours, and at most "Moderate".
create or replace function public.forecast_day(p_day date default null)
returns table (hour smallint, crowd numeric, level smallint, level_name text, wait_minutes int,
               is_past boolean, is_recommended boolean, is_best boolean)
language sql stable set search_path = '' as $$
  with ctx as (
    select (now() at time zone public.user_tz()) as local_now
  ), d as (
    select coalesce(p_day, c.local_now::date) as day, c.local_now from ctx c
  ), base as (
    select e.hour_of_day as hr, e.crowd as cr, public.level_of(e.crowd) as lv,
           (d.day < d.local_now::date
            or (d.day = d.local_now::date and e.hour_of_day <= extract(hour from d.local_now))) as past
    from public.usage_estimates e cross join d
    where e.weekday = extract(isodow from d.day)::int - 1
  ), ranked as (
    select b.*, row_number() over (partition by b.past order by b.cr, b.hr) as rn from base b
  )
  select r.hr, r.cr, r.lv, public.level_name(r.lv), (array[0, 5, 15, 25])[r.lv + 1], r.past,
         (not r.past and r.rn <= 3 and r.lv <= 1),
         (not r.past and r.rn = 1 and r.lv <= 1)
  from ranked r order by r.hr
$$;

-- Day strip for the planner: next N days with that weekday's average crowd level.
create or replace function public.forecast_days(p_count int default 28)
returns table (day date, weekday smallint, avg_level smallint, is_today boolean)
language sql stable set search_path = '' as $$
  with t as (select (now() at time zone public.user_tz())::date as today),
  wk as (select e.weekday as wd, avg(e.crowd) as a from public.usage_estimates e group by e.weekday)
  select (t.today + g)::date, (extract(isodow from t.today + g)::int - 1)::smallint,
         public.level_of(wk.a), g = 0
  from t cross join generate_series(0, greatest(1, least(p_count, 60)) - 1) g
  join wk on wk.wd = extract(isodow from t.today + g)::int - 1
  order by g
$$;

-- Best time to do laundry: today if a quiet hour is left, otherwise tomorrow.
create or replace function public.best_time()
returns table (day date, hour smallint, level smallint, level_name text, crowd numeric,
               starts_at timestamptz, is_today boolean, alt_hours smallint[], est_in_use int)
language plpgsql stable set search_path = '' as $$
declare
  v_tz    text := public.user_tz();
  v_today date := (now() at time zone public.user_tz())::date;
  v_day   date := (now() at time zone public.user_tz())::date;
  v_hour  smallint;
  v_crowd numeric;
  v_res   public.residences := public.current_residence();
begin
  select f.hour into v_hour from public.forecast_day(v_day) f where f.is_best;
  if v_hour is null then
    v_day := v_today + 1;
    select f.hour into v_hour from public.forecast_day(v_day) f where f.is_best;
  end if;
  v_hour := coalesce(v_hour, 15);
  select e.crowd into v_crowd from public.usage_estimates e
    where e.weekday = extract(isodow from v_day)::int - 1 and e.hour_of_day = v_hour;
  return query select
    v_day, v_hour, public.level_of(v_crowd), public.level_name(public.level_of(v_crowd)), v_crowd,
    make_timestamptz(extract(year from v_day)::int, extract(month from v_day)::int,
                     extract(day from v_day)::int, v_hour, 0, 0, v_tz),
    v_day = v_today,
    array(select f.hour from public.forecast_day(v_day) f
          where f.is_recommended and not f.is_best order by f.crowd, f.hour),
    round(v_res.washer_count * v_crowd * 0.9)::int;
end $$;

create or replace function public.insights_summary()
returns table (busiest_weekday smallint, quietest_weekday smallint, busiest_hour smallint, quietest_hour smallint)
language sql stable set search_path = '' as $$
  with wd as (select e.weekday as k, avg(e.crowd) as a from public.usage_estimates e group by e.weekday),
       hr as (select e.hour_of_day as k, avg(e.crowd) as a from public.usage_estimates e group by e.hour_of_day)
  select (select w.k from wd w order by w.a desc, w.k limit 1),
         (select w.k from wd w order by w.a, w.k limit 1),
         (select h.k from hr h order by h.a desc, h.k limit 1),
         (select h.k from hr h order by h.a, h.k limit 1)
$$;

-- "~N of M machines in use" for a weekday/hour at the caller's residence.
create or replace function public.estimate_in_use(p_weekday smallint, p_hour smallint)
returns int language sql stable set search_path = '' as $$
  select round((public.current_residence()).washer_count * least(1, e.crowd))::int
  from public.usage_estimates e where e.weekday = p_weekday and e.hour_of_day = p_hour
$$;

create view public.forecast_heatmap with (security_invoker = true) as
  select e.weekday, e.hour_of_day, e.crowd, public.level_of(e.crowd) as level
  from public.usage_estimates e;

create view public.residence_overview with (security_invoker = true) as
  select r.id, r.name, r.washer_count, r.dryer_count, r.typical_in_use,
         greatest(r.washer_count - r.typical_in_use, 0) as estimated_free,
         r.timezone, r.sort_order
  from public.residences r;

------------------------------------------------------------------------------
-- 4. Sessions: clients read through a view and write only through functions
------------------------------------------------------------------------------
create view public.my_sessions with (security_invoker = true) as
  select s.*,
    case s.status
      when 'planned'   then 'planned'
      when 'collected' then 'collected'
      else case when s.ends_at <= now() then 'finished' else 'running' end
    end as phase,
    case when s.status = 'active' then greatest(0, extract(epoch from s.ends_at - now()))::int end as seconds_remaining,
    case when s.status = 'active' then extract(epoch from s.ends_at - s.started_at)::int end as total_seconds
  from public.sessions s;

create or replace function public._require_user() returns uuid
language plpgsql stable set search_path = '' as $$
declare u uuid := (select auth.uid());
begin
  if u is null then raise exception 'Please log in first.' using errcode = '28000'; end if;
  return u;
end $$;

create or replace function public._slot_start(p_day date, p_hour int)
returns timestamptz language plpgsql stable set search_path = '' as $$
declare v timestamptz;
begin
  if p_hour not between 7 and 23 then raise exception 'Pick an hour between 07:00 and 23:00.'; end if;
  v := make_timestamptz(extract(year from p_day)::int, extract(month from p_day)::int,
                        extract(day from p_day)::int, p_hour, 0, 0, public.user_tz());
  if v <= now() then raise exception 'That time has already started. Pick a later slot.'; end if;
  return v;
end $$;

create or replace function public.plan_session(
  p_day date, p_hour int, p_kind public.session_kind, p_cycle text, p_minutes int, p_remind boolean default true)
returns public.sessions language plpgsql security definer set search_path = '' as $$
declare u uuid := public._require_user(); r public.sessions;
begin
  if p_minutes not between 10 and 180 then raise exception 'Duration must be between 10 and 180 minutes.'; end if;
  insert into public.sessions (user_id, status, kind, cycle_label, planned_start, duration_minutes,
                               remind_5, remind_end, remind_collect)
  values (u, 'planned', p_kind, p_cycle, public._slot_start(p_day, p_hour), p_minutes, p_remind, p_remind, p_remind)
  returning * into r;
  return r;
end $$;

create or replace function public.update_planned_session(
  p_id uuid, p_day date, p_hour int, p_kind public.session_kind, p_cycle text, p_minutes int, p_remind boolean default true)
returns public.sessions language plpgsql security definer set search_path = '' as $$
declare u uuid := public._require_user(); r public.sessions;
begin
  if p_minutes not between 10 and 180 then raise exception 'Duration must be between 10 and 180 minutes.'; end if;
  update public.sessions s
     set planned_start = public._slot_start(p_day, p_hour), kind = p_kind, cycle_label = p_cycle,
         duration_minutes = p_minutes, remind_5 = p_remind, remind_end = p_remind, remind_collect = p_remind
   where s.id = p_id and s.user_id = u and s.status = 'planned'
  returning * into r;
  if not found then raise exception 'Planned session not found.'; end if;
  return r;
end $$;

create or replace function public.cancel_planned_session(p_id uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare u uuid := public._require_user();
begin
  delete from public.sessions s where s.id = p_id and s.user_id = u and s.status = 'planned';
  if not found then raise exception 'Planned session not found.'; end if;
end $$;

-- Start a timer, either fresh or from a planned session. The end time comes from the
-- database clock, so a wrong device clock cannot break reminders.
create or replace function public.start_timer(
  p_machine text, p_cycle text, p_kind public.session_kind, p_minutes int,
  p_time_scale int default 1, p_from_planned uuid default null)
returns public.sessions language plpgsql security definer set search_path = '' as $$
declare
  u uuid := public._require_user();
  r public.sessions;
  v_secs int;
  v_remind boolean := coalesce((select p.reminders_default from public.profiles p where p.id = u), true);
begin
  if p_minutes not between 1 and 240 then raise exception 'Duration must be between 1 and 240 minutes.'; end if;
  if p_time_scale not in (1, 60) then raise exception 'Invalid timer speed.'; end if;
  if length(btrim(coalesce(p_machine, ''))) = 0 then raise exception 'Machine name is required.'; end if;
  v_secs := greatest(1, round(p_minutes * 60.0 / p_time_scale))::int;

  if p_from_planned is not null then
    update public.sessions s
       set status = 'active', machine_label = p_machine, cycle_label = p_cycle, kind = p_kind,
           duration_minutes = p_minutes, started_at = now(), ends_at = now() + make_interval(secs => v_secs),
           time_scale = p_time_scale, notified_5 = false, notified_end = false, notified_collect = false
     where s.id = p_from_planned and s.user_id = u and s.status = 'planned'
    returning * into r;
    if not found then raise exception 'Planned session not found.'; end if;
  else
    insert into public.sessions (user_id, status, kind, machine_label, cycle_label, duration_minutes,
                                 started_at, ends_at, time_scale, remind_5, remind_end, remind_collect)
    values (u, 'active', p_kind, p_machine, p_cycle, p_minutes, now(), now() + make_interval(secs => v_secs),
            p_time_scale, v_remind, v_remind, v_remind)
    returning * into r;
  end if;
  return r;
end $$;

create or replace function public.collect_session(p_id uuid)
returns public.sessions language plpgsql security definer set search_path = '' as $$
declare u uuid := public._require_user(); r public.sessions;
begin
  update public.sessions s set status = 'collected', collected_at = now()
   where s.id = p_id and s.user_id = u and s.status = 'active'
  returning * into r;
  if not found then raise exception 'Active timer not found.'; end if;
  return r;
end $$;

create or replace function public.set_session_reminders(p_id uuid, p_enabled boolean)
returns public.sessions language plpgsql security definer set search_path = '' as $$
declare u uuid := public._require_user(); r public.sessions;
begin
  update public.sessions s set remind_5 = p_enabled, remind_end = p_enabled, remind_collect = p_enabled
   where s.id = p_id and s.user_id = u and s.status in ('planned', 'active')
  returning * into r;
  if not found then raise exception 'Session not found.'; end if;
  return r;
end $$;

------------------------------------------------------------------------------
-- 5. Reminders: generated by the database on a schedule
------------------------------------------------------------------------------
create or replace function public.process_reminders()
returns void language plpgsql security definer set search_path = '' as $$
begin
  -- 5 minutes left (only for cycles longer than 5 minutes)
  with due as (
    update public.sessions s set notified_5 = true
     where s.status = 'active' and not s.notified_5 and s.ends_at > now()
       and s.ends_at - now() <= interval '5 minutes'
       and s.ends_at - s.started_at > interval '5 minutes'
    returning s.user_id, s.machine_label, s.remind_5
  )
  insert into public.notifications (user_id, title, body)
  select d.user_id, d.machine_label || ' ends in 5 minutes', 'Head back to the laundry room.'
  from due d
  where d.remind_5 and coalesce((select p.reminders_default from public.profiles p where p.id = d.user_id), true);

  -- finished
  with due as (
    update public.sessions s set notified_end = true
     where s.status = 'active' and not s.notified_end and s.ends_at <= now()
    returning s.user_id, s.machine_label, s.remind_end
  )
  insert into public.notifications (user_id, title, body)
  select d.user_id, d.machine_label || ' has finished', 'Your clothes are ready to collect.'
  from due d
  where d.remind_end and coalesce((select p.reminders_default from public.profiles p where p.id = d.user_id), true);

  -- still not collected 10 minutes later (scaled in demo mode)
  with due as (
    update public.sessions s set notified_collect = true
     where s.status = 'active' and s.notified_end and not s.notified_collect
       and (now() - s.ends_at) * s.time_scale >= interval '10 minutes'
    returning s.user_id, s.machine_label, s.remind_collect
  )
  insert into public.notifications (user_id, title, body)
  select d.user_id, 'Clothes still in ' || d.machine_label, 'Collect them so others can use the machine.'
  from due d
  where d.remind_collect and coalesce((select p.reminders_default from public.profiles p where p.id = d.user_id), true);
end $$;

create extension if not exists pg_cron with schema pg_catalog;
do $$ begin
  perform cron.unschedule('laundrylink-process-reminders');
exception when others then null;
end $$;
select cron.schedule('laundrylink-process-reminders', '10 seconds', 'select public.process_reminders()');

------------------------------------------------------------------------------
-- 6. Privileges + RLS
------------------------------------------------------------------------------
-- sessions: read-only for clients (all writes go through the functions above)
drop policy if exists "sessions own" on public.sessions;
create policy "sessions select own" on public.sessions
  for select to authenticated using (user_id = (select auth.uid()));
revoke all on public.sessions from anon;
revoke insert, update, delete on public.sessions from authenticated;

-- notifications: read + clear own; only the server creates them
drop policy if exists "notifications own" on public.notifications;
create policy "notifications select own" on public.notifications
  for select to authenticated using (user_id = (select auth.uid()));
create policy "notifications delete own" on public.notifications
  for delete to authenticated using (user_id = (select auth.uid()));
revoke all on public.notifications from anon;
revoke insert, update on public.notifications from authenticated;

-- views
revoke all on public.my_sessions from anon;
grant select on public.my_sessions to authenticated;
grant select on public.forecast_heatmap, public.residence_overview to anon, authenticated;

-- functions: lock everything down, then open up what each role needs
revoke all on function
  public.level_of(numeric), public.level_name(smallint), public.current_residence(), public.user_tz(),
  public.server_time(), public.forecast_day(date), public.forecast_days(int), public.best_time(),
  public.insights_summary(), public.estimate_in_use(smallint, smallint),
  public._require_user(), public._slot_start(date, int),
  public.plan_session(date, int, public.session_kind, text, int, boolean),
  public.update_planned_session(uuid, date, int, public.session_kind, text, int, boolean),
  public.cancel_planned_session(uuid),
  public.start_timer(text, text, public.session_kind, int, int, uuid),
  public.collect_session(uuid), public.set_session_reminders(uuid, boolean),
  public.process_reminders()
  from public, anon, authenticated;

-- public read-only helpers (landing page works signed out)
grant execute on function
  public.level_of(numeric), public.level_name(smallint), public.current_residence(), public.user_tz(),
  public.server_time(), public.forecast_day(date), public.forecast_days(int), public.best_time(),
  public.insights_summary(), public.estimate_in_use(smallint, smallint)
  to anon, authenticated;

-- signed-in only
grant execute on function
  public._require_user(), public._slot_start(date, int),
  public.plan_session(date, int, public.session_kind, text, int, boolean),
  public.update_planned_session(uuid, date, int, public.session_kind, text, int, boolean),
  public.cancel_planned_session(uuid),
  public.start_timer(text, text, public.session_kind, int, int, uuid),
  public.collect_session(uuid), public.set_session_reminders(uuid, boolean)
  to authenticated;
-- process_reminders(): nobody but the scheduler (postgres) can run it.

------------------------------------------------------------------------------
-- 7. Realtime
------------------------------------------------------------------------------
alter publication supabase_realtime add table public.sessions, public.notifications;
